<?php
declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');header('X-Content-Type-Options: nosniff');
if(($_SERVER['REQUEST_METHOD']??'')!=='GET'){http_response_code(405);exit;}
$region=(string)($_GET['region']??'');$server=strtolower((string)($_GET['server']??''));$name=(string)($_GET['name']??'');if(!in_array($region,['la','eu','nae','naw','as'],true)||!preg_match('/^[a-z0-9-]{2,30}$/D',$server)||mb_strlen($name)<1||mb_strlen($name)>50||preg_match('/[\x00-\x1f\/\\\\]/',$name)){http_response_code(400);echo '{"error":"Personaje no válido."}';exit;}
$dir=(getenv('AION_PRIVATE_DIR')?:dirname(__DIR__,2).'/aion2-private').'/cache';$key=hash('sha256',$region.'/'.$server.'/'.$name);$path=$dir.'/history-'.$key.'.json';$prior=is_file($path)?json_decode(file_get_contents($path),true):null;if($prior&&time()-$prior['cachedAt']<300){echo json_encode($prior,JSON_UNESCAPED_UNICODE);exit;}
$rate=fopen($dir.'/history-limit-'.hash('sha256',($_SERVER['REMOTE_ADDR']??'').date('YmdHi')),'c+');flock($rate,LOCK_EX);$n=(int)stream_get_contents($rate);if($n>=20){http_response_code(429);header('Retry-After: 60');echo '{"error":"Espera un minuto antes de consultar más historiales."}';exit;}rewind($rate);ftruncate($rate,0);fwrite($rate,(string)($n+1));fclose($rate);
function arrayAfter(string $text,string $key):?array{$start=strpos($text,$key);if($start===false)return null;$start+=strlen($key)-1;$depth=0;$quoted=false;$escaped=false;for($i=$start,$len=strlen($text);$i<$len;$i++){$c=$text[$i];if($quoted){if($escaped)$escaped=false;elseif($c==='\\')$escaped=true;elseif($c==='"')$quoted=false;continue;}if($c==='"'){$quoted=true;continue;}if($c==='[')$depth++;if($c===']'&&--$depth===0)return json_decode(substr($text,$start,$i-$start+1),true);}return null;}
$h=fopen($path.'.lock','c');flock($h,LOCK_EX);
try{$url='https://aion2index.com/c/'.$region.'/'.$server.'/'.rawurlencode($name).'/history?range=30';$c=curl_init($url);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>20,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_USERAGENT=>'FullAIon2Companion/1.0 (+https://governanceai.me)']);$html=curl_exec($c);$code=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);if($code!==200||!is_string($html))throw new RuntimeException();$doc=new DOMDocument();@$doc->loadHTML('<?xml encoding="UTF-8">'.$html);$rsc='';foreach($doc->getElementsByTagName('script') as $script){if(preg_match('/^self\.__next_f\.push\(\[1,([\s\S]*)\]\)$/',$script->textContent,$m)){$part=json_decode($m[1],true);if(is_string($part))$rsc.=$part;}}$points=arrayAfter($rsc,'"points":[');$events=arrayAfter($rsc,'"initial":[');if(!is_array($points))throw new RuntimeException();$points=array_values(array_filter($points,fn($p)=>is_string($p['t']??null)&&is_numeric($p['value']??null)&&$p['value']>=0&&$p['value']<1e9));$data=['source'=>$url,'region'=>$region,'server'=>$server,'name'=>$name,'fetchedAt'=>gmdate('c'),'cachedAt'=>time(),'stale'=>false,'points'=>array_slice($points,-500),'events'=>array_slice($events??[],0,50)];$tmp=$path.'.tmp';file_put_contents($tmp,json_encode($data,JSON_UNESCAPED_UNICODE),LOCK_EX);chmod($tmp,0600);rename($tmp,$path);echo json_encode($data,JSON_UNESCAPED_UNICODE);
}catch(Throwable){if($prior){$prior['stale']=true;echo json_encode($prior,JSON_UNESCAPED_UNICODE);}else{http_response_code(502);echo '{"error":"La fuente no publica historial disponible para este personaje."}';}}
